css:
.quote{position:absolute; top:-10px; left:0; z-index:2;
  writing-mode:vertical-rl; line-height:2.0}
.quote span{                                  /* 行ごとに分けず1本のspanでよい */
  background:#fff; padding:.5em .35em;
  box-decoration-break:clone;
  -webkit-box-decoration-break:clone}         /* ← これが無いと矩形の白箱に戻る */
